"""Explain handle bit budgets, record layout and independent options."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1921': ('주소 전체 대신 몇 번 상자의 몇 번째 칸인지 적으면 작은 번호표로 위치를 나타낼 수 있어요. 칸의 간격이 일정하면 더 적은 자리로 표시할 수 있어요.', '페이지 크기에 따라 pool 크기와 위치 비트 수가 달라짐을 계산합니다.', '4096바이트 페이지 4개는 16384바이트예요. 16바이트 단위 위치가 몇 개인지 16384÷16=1024로 계산하세요.', ['handle은 32비트 정수예요. 비트는 0 또는 1을 담는 한 자리예요. 이 번호는 pool 번호, pool 안 위치인 offset, 추가 정보 extra로 나뉘어요. extra에는 5비트를 배정하고 나머지 자리를 위치 표시에 써요.', '페이지는 운영체제가 메모리를 관리할 때 쓰는 일정 크기의 묶음이에요. PAGE_SHIFT가 12이면 페이지 크기는 2의 12승인 4096바이트예요. 2의 12승은 2를 열두 번 곱한 수예요. KiB는 1024바이트를 나타내는 단위라 한 페이지는 4KiB예요.', 'DEPOT_POOL_ORDER가 2라 pool 하나는 2의 2승인 4페이지예요. 따라서 4096×4=16384바이트, 즉 16KiB예요. order 2가 2페이지라는 뜻이 아니라 2를 두 번 곱한 4페이지라는 점을 기억하세요.', '기록 시작은 16바이트 간격에 맞추므로 바이트 위치를 그대로 적지 않고 16으로 나눈 값을 적어요. 16KiB pool에는 1024개의 이런 위치 단위가 있고, 0~1023을 적는 데 10비트가 필요해요. 식으로는 2+12-4=10이고 마지막 4는 16이 2의 4승이기 때문에 빼요.', 'PAGE_SHIFT가 16이면 페이지는 65536바이트, pool은 262144바이트인 256KiB예요. 16바이트 단위 위치는 16384개라 14비트가 필요해요. 공식도 2+16-4=14예요. 전체 32비트에서 offset 14와 extra 5를 빼면 pool 번호 부분은 13비트가 남아요.', 'PAGE_SHIFT 12에서는 17+10+5=32, PAGE_SHIFT 16에서는 13+14+5=32예요. pool이 커지면 그 안 위치에 더 많은 비트가 필요해 pool 번호 자리가 줄어요. 이 계산은 자리 수의 배분이며 실제 전체 정수 안에서 각 자리가 놓이는 배치는 컴파일러와 기종의 약속을 따라요.'], [('PAGE_SHIFT가 12이고 pool order가 2이면 pool 크기는 얼마인가요?', ['4096바이트 한 페이지예요', '16KiB예요'], '정답은 두 번째예요. 페이지 하나는 4096바이트이고 pool은 2의 2승인 4페이지예요. 4096×4=16384바이트, 16384÷1024=16KiB예요.'), ('PAGE_SHIFT가 16일 때 offset에 필요한 비트 수는 얼마인가요?', ['14비트예요', '페이지 크기와 관계없이 언제나 10비트예요'], '정답은 첫 번째예요. pool 크기의 단계 2+16에서 16바이트 단위를 나타내는 단계 4를 빼요. 2+16-4=14이므로 큰 pool의 더 많은 위치를 나타낼 수 있어요.')]), 'os1922': ('책을 찾는 목록과 반납한 책을 다시 정리하는 목록은 목적이 달라요. 기록 안에서도 두 목록의 연결 칸을 구별해야 해요.', 'stack_record의 서로 다른 목록 연결과 union 사용 상태를 이해합니다.', '구조체를 두 영역으로 그리세요. 별도 hash_list 칸과 entries 또는 free_list·rcu_state를 넣는 공유 칸이에요.', ['stack_record는 호출 경로 하나를 담는 관리표예요. hash는 검색용 요약 숫자, size는 호출 위치 개수, handle은 위치 번호, count는 보관 권리 수예요. entries 배열에는 실제 호출 위치들을 담아요.', 'hash_list는 같은 검색 묶음 안의 기록들을 이어 주는 연결 정보예요. free_list는 사용이 끝난 기록들을 재사용 대기 목록으로 이어 주는 연결 정보예요. 둘은 이름만 다른 같은 칸이 아니라 구조체의 서로 다른 항목이에요.', '다만 free_list와 RCU 상태표 rcu_state는 entries와 같은 메모리 영역을 나눠 써요. C의 union은 여러 용도를 겹친 자리에 놓는 표현이에요. 예를 들어 한 상자를 사용 중에는 물건 보관에, 반납 뒤에는 정리표 보관에 쓰는 것과 비슷해요.', '별도 영역을 늘 따로 두지 않으므로 공간을 아낄 수 있어요. 하지만 호출 위치를 담은 바이트를 정리표 주소로 읽으면 엉뚱한 값으로 해석할 수 있어요. 공간이 존재한다는 것과 그 안의 정보가 지금 그 용도로 유효하다는 것은 달라요.', '헤더의 약속은 참조 수 0인 재사용 대기 기록에서 관리 영역을 사용한다는 것이에요. 대기 목록을 나와 다시 참조 수가 0이 아니게 되면 free_list와 rcu_state를 임의로 건드리지 않아요. 이렇게 계속 지켜야 할 조건을 불변식이라고 불러요.', '옛 검색이 기록을 아직 볼 수 있는 경우는 RCU와 참조 수 확보 규칙을 함께 다뤄요. union이 자동으로 잠금을 걸거나 읽기를 기다려 주지는 않아요. 구조체 그림에서 hash_list는 공유 영역 밖에 따로 그리고, entries와 free_list·rcu_state만 같은 영역의 두 용도로 표시하세요.'], [('hash_list와 free_list는 같은 필드에 붙인 두 이름인가요?', ['네. 같은 칸을 부르는 이름만 달라요', '아니요. 검색 연결과 재사용 연결을 위한 별도 필드예요'], '정답은 두 번째예요. hash_list는 union 밖이고 free_list는 entries와 공유하는 영역 안이에요. 두 연결의 역할과 실제 위치를 함께 구별해야 해요.'), ('사용 중인 유효한 기록의 free_list를 마음대로 관리 정보로 읽어도 되나요?', ['아니요. 현재는 entries 용도로 쓰는 영역이라는 약속을 지켜요', '네. union의 모든 표현은 언제나 동시에 유효해요'], '정답은 첫 번째예요. 같은 바이트가 호출 위치를 담고 있을 수 있어요. 공간 공유는 어느 상태에서 어느 표현을 사용하는지 정한 규칙과 함께 써야 해요.')]), 'os1923': ('새 상자를 사도 된다는 허락과 물건을 보관해 달라는 권리는 달라요. 두 선택을 각각 켜거나 끌 수 있어요.', 'CAN_ALLOC과 GET의 독립적인 역할과 기존 공간 사용을 이해합니다.', '옵션 값 0·1·2·3을 적고 각각 두 표시가 꺼짐·할당만·GET만·둘 다라고 표시하세요.', ['flag는 선택 기능을 나타내는 비트 표시예요. CAN_ALLOC은 값 1이고 GET은 값 2라 두 개를 함께 켜면 3이에요. 이 두 자리의 의미는 서로 바꾸어 해석하면 안 돼요.', 'CAN_ALLOC은 새 pool, 즉 메모리 묶음을 얻기 위해 alloc_pages를 호출해도 된다는 선택이에요. 꺼져 있으면 새 페이지를 요청하는 분기를 건너뛰어요. 이미 있는 기록을 찾거나 미리 확보한 메모리 공간을 이용하는 것까지 금지하지는 않아요.', 'GET은 기록을 보관할 권리를 참조 수로 관리하는 선택이에요. 정상적으로 새 GET 기록을 만들면 권리 하나로 시작하고, 이미 살아 있는 같은 기록을 GET으로 찾으면 권리를 하나 더 얻어요. 필요가 끝나면 그 권리에 맞춰 put을 해야 해요.', '값 2인 GET만 켰다고 해 봐요. 같은 기록이 이미 있다면 새 페이지 없이 찾아서 권리를 얻을 수 있어요. 새 기록이어도 현재 pool의 여유, 예비 pool 또는 안전하게 재사용할 기록이 충분하면 저장할 수 있어요. 모든 필요한 자원이 없고 새 할당도 못 하면 번호 0으로 실패할 수 있어요.', '값 1인 CAN_ALLOC만 켜면 새 페이지 요청을 허용하지만 GET의 참조 관리 방식은 선택하지 않은 것이에요. 공간 준비를 허용했다고 나중에 put할 권리를 얻었다고 생각하면 안 돼요. 기록의 수명 정책을 일관되게 지켜야 해요.', 'gfp_flags라는 다른 인수는 메모리를 어떤 조건으로 얻을지 지정해요. depot_flags는 여기서 배운 저장소 옵션이에요. 둘은 서로 다른 인수이며 CAN_ALLOC을 켜도 현재 잠금이나 인터럽트 상황에서 실제 할당이 허용되는지는 호출하는 쪽이 맞춰야 해요.'], [('GET 방식으로 성공해 확보한 보관 권리에는 어떤 책임이 따라오나요?', ['모든 상황에서 메모리를 할당해도 된다는 뜻이에요', '필요가 끝나면 대응하는 put으로 권리를 돌려줘야 해요'], '정답은 두 번째예요. GET은 기록의 수명 관리 선택이에요. 새 pool 할당을 허용하는 CAN_ALLOC과 역할이 달라요.'), ('CAN_ALLOC을 끄면 모든 저장 요청이 반드시 실패하나요?', ['아니요. 기존 기록이나 이미 확보한 공간으로 처리할 수 있어요', '네. 기존 기록 검색까지 전부 생략해요'], '정답은 첫 번째예요. 첫 검색은 할당 분기보다 먼저 해요. 새 페이지를 요청하지 않는다는 조건과 이미 가진 자원을 쓰지 못한다는 조건은 달라요.')]), 'os1924': ('설명서와 실제 스위치 동작이 다르면 둘을 나란히 확인해야 해요. 설명서의 한 문장을 외우는 대신 어떤 조건에서 무엇을 실행하는지 읽어요.', '주석과 실제 분기의 차이를 근거로 설명하는 방법을 익힙니다.', 'can_alloc=false이면 할당 분기 생략, true이고 예비 공간 없음이면 시도라고 두 경우를 적으세요.', ['Context는 함수를 어떤 실행 상황에서 부를 수 있는지 설명하는 문서 항목이에요. 실행 상황에는 이미 잡은 잠금이나 인터럽트 안인지 같은 조건이 포함돼요. 메모리를 새로 얻는 함수도 이런 상황의 제한을 받아요.', '이 프로젝트가 사용하는 Linux v6.12 헤더에는 alloc_pages를 사용할 수 없는 상황에서 CAN_ALLOC 설정이 필요하다는 문장이 있어요. 하지만 같은 헤더의 옵션 설명은 CAN_ALLOC이 새 메모리 확보를 허용한다고 적고, 구현도 그 방향으로 동작해요. 서로 어긋나는 표현을 구분해서 읽어야 해요.', '실제 코드는 depot_flags에서 CAN_ALLOC 자리를 검사해 can_alloc을 정해요. 이어 기존 기록을 못 찾았고 can_alloc이 참이며 new_pool이 없으면 alloc_pages를 불러요. &&는 두 조건이 모두 맞아야 한다는 뜻이고 !new_pool은 예비 공간 표시가 비었다는 뜻이에요.', '그러므로 CAN_ALLOC을 켜면 할당을 피한다고 설명할 수 없어요. 예비 공간이 없을 때 새 페이지를 요청할 수 있게 하는 선택이에요. can_alloc이 거짓이면 이 요청 분기를 건너뛰고 이미 확보된 자원으로 처리할 수 있는지 뒤에서 확인해요.', '새 할당은 이 함수 자신의 pool_lock을 잡기 전이지만 호출한 쪽이 이미 다른 잠금을 잡고 있을 수 있어요. 이 함수의 잠금 밖이라는 사실만으로 모든 상황에서 안전하다고 결론 내리면 안 돼요. 실제 호출 위치와 메모리 할당 방법의 조건을 함께 확인해야 해요.', '이 수업의 읽기 방법은 문서 문장, 실제 if 조건, 그 안의 함수 호출을 나란히 적는 것이에요. 차이를 숨기거나 원문이 언제나 완벽하다고 가정하지 않아요. 종이의 두 조건 예시는 분기를 이해하는 연습이며 모든 인터럽트·잠금 상황에서 커널을 실행해 본 검증은 아니에요.'], [('실제 코드에서 can_alloc이 참이면 언제나 새 메모리 할당을 피하나요?', ['네. 참이면 절대로 할당하지 않아요', '아니요. 예비 공간이 없으면 할당을 시도할 수 있어요'], '정답은 두 번째예요. can_alloc && !READ_ONCE(new_pool) 조건 안에 alloc_pages가 있어요. 참이라는 값은 이 할당 시도를 허용하는 쪽으로 쓰여요.'), ('헤더 설명의 한 문장과 구현의 조건이 어긋나면 어떻게 공부해야 하나요?', ['차이를 적고 실제 분기와 호출 상황의 약속을 함께 확인해요', '차이는 지우고 둘이 같은 뜻이라고 외워요'], '정답은 첫 번째예요. 주석도 읽되 실행을 결정하는 조건과 함수 호출을 대조해야 해요. 차이를 감추면 옵션의 의미를 반대로 배울 수 있어요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_476.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
